{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "len(stdin.splitlines()) == 2",
      "description": "The input must consist of exactly two lines."
    },
    {
      "id": "P2",
      "expression": "all(1 <= len(s) <= 200000 for s in stdin.splitlines())",
      "description": "Each string must have a length between 1 and 200,000."
    },
    {
      "id": "P3",
      "expression": "stdin.splitlines()[0] == stdin.splitlines()[1] or len(stdin.splitlines()[0]) == len(stdin.splitlines()[1])",
      "description": "The two strings must either be equal or have the same length."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == 'YES'",
      "description": "Output 'YES' if the two strings are equivalent."
    },
    {
      "id": "Q2",
      "expression": "stdout == 'NO'",
      "description": "Output 'NO' if the two strings are not equivalent."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 10",
      "description": "The number of test cases T must be between 1 and 10."
    },
    {
      "id": "P2",
      "expression": "1 <= N <= 10**5",
      "description": "The length of the string S must be between 1 and 100,000."
    },
    {
      "id": "P3",
      "expression": "1 <= K <= 10**9",
      "description": "The number of repetitions K must be at least 1 and can be as large as 1 billion."
    },
    {
      "id": "P4",
      "expression": "len(S) == N and all(c in 'abcdefghijklmnopqrstuvwxyz' for c in S)",
      "description": "The string S must have a length equal to N and consist only of lowercase English letters."
    },
    {
      "id": "P5",
      "expression": "1 <= N * K <= 10**9",
      "description": "The total length of the new string formed by repeating S must not exceed 1 billion."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == str(count_ab_subsequences(S, K))",
      "description": "The output must be the count of subsequences 'ab' in the new string formed by repeating S K times."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "binary_to_string",
    "signature": "binary_to_string(binary_str: str) -> str"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(binary_str, str)",
      "description": "The input must be a string."
    },
    {
      "id": "P2",
      "expression": "all(c in '01' for c in binary_str)",
      "description": "The input string must contain only '0' and '1'."
    },
    {
      "id": "P3",
      "expression": "len(binary_str) % 8 == 0",
      "description": "The length of the input string must be a multiple of 8."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "return_value == ''.join(chr(int(binary_str[i:i+8], 2)) for i in range(0, len(binary_str), 8))",
      "description": "The returned string is the ASCII decoded text from the binary string."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= r_1 <= 8 and 1 <= c_1 <= 8 and 1 <= r_2 <= 8 and 1 <= c_2 <= 8",
      "description": "The starting and final fields must be within the bounds of the chessboard."
    },
    {
      "id": "P2",
      "expression": "(r_1, c_1) != (r_2, c_2)",
      "description": "The starting field must not coincide with the final field."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == '0 0 0' or stdout == '1 0 1' or stdout == '2 1 3' or stdout == '1 1 1' or stdout == '2 0 2' or stdout == '1 2 1' or stdout == '2 2 1' or stdout == '1 2 2' or stdout == '2 1 2'",
      "description": "The output must consist of three space-separated integers representing the minimum moves for the rook, bishop, and king respectively."
    },
    {
      "id": "Q2",
      "expression": "any(int(x) >= 0 for x in stdout.split())",
      "description": "Each of the output integers must be non-negative."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "sort_my_string",
    "signature": "def sort_my_string(s: str) -> str"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "isinstance(s, str)",
      "description": "Input s must be a string."
    },
    {
      "id": "P2",
      "expression": "len(s) > 0",
      "description": "Input string s must not be empty."
    },
    {
      "id": "P3",
      "expression": "all(c.isalpha() for c in s)",
      "description": "All characters in the input string s must be alphabetic."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(return_value.split()) == 2",
      "description": "The output must contain exactly two groups separated by a space."
    },
    {
      "id": "Q2",
      "expression": "all(return_value.split()[0][i] == s[i * 2] for i in range(len(return_value.split()[0])))",
      "description": "The first group in the output must consist of characters from even indices of s."
    },
    {
      "id": "Q3",
      "expression": "all(return_value.split()[1][i] == s[i * 2 + 1] for i in range(len(return_value.split()[1])))",
      "description": "The second group in the output must consist of characters from odd indices of s."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 500",
      "description": "The number of test cases T must be between 1 and 500."
    },
    {
      "id": "P2",
      "expression": "1 <= N <= 50",
      "description": "The number of stacks N in each test case must be between 1 and 50."
    },
    {
      "id": "P3",
      "expression": "1 <= len(B) <= 50 for all B in stacks",
      "description": "Each stack represented by a binary string B must have a length between 1 and 50."
    },
    {
      "id": "P4",
      "expression": "S in {'Dee', 'Dum'}",
      "description": "The starting player S must be either 'Dee' or 'Dum'."
    },
    {
      "id": "P5",
      "expression": "all(c in {'0', '1'} for B in stacks for c in B)",
      "description": "Each character in the stacks must be either '0' or '1'."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout in {'Dee', 'Dum'}",
      "description": "The output must be either 'Dee' or 'Dum' indicating the winner of the match."
    },
    {
      "id": "Q2",
      "expression": "len(stdout) == 3 or len(stdout) == 3",
      "description": "The output must be exactly 3 characters long."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "functional",
    "class_name": null,
    "function_name": "tree_by_levels",
    "signature": "node -> list"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "node is None or isinstance(node, Node)",
      "description": "The input node must be either None or an instance of Node."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == []",
      "description": "If the input node is None, the output must be an empty list."
    },
    {
      "id": "Q2",
      "expression": "len(stdout) == count_nodes(node)",
      "description": "The output list must contain the same number of elements as the number of nodes in the tree."
    },
    {
      "id": "Q3",
      "expression": "all(stdout[i] == value_at_level(node, level, i) for level in range(depth(node)) for i in range(count_at_level(node, level)))",
      "description": "The output list must contain elements from the tree in level order."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 100",
      "description": "The number of test cases T must be between 1 and 100."
    },
    {
      "id": "P2",
      "expression": "2 <= len(s) <= 10**5",
      "description": "The length of the string s must be between 2 and 100,000."
    },
    {
      "id": "P3",
      "expression": "all(c in 'abcdefghijklmnopqrstuvwxyz' for c in s)",
      "description": "The string s must contain only lowercase English letters."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout in {'YES', 'NO'}",
      "description": "The output for each test case must be either 'YES' or 'NO'."
    },
    {
      "id": "Q2",
      "expression": "any((s[:i] + s[i+1:]) == (s[:i] + s[i+1:])[::-1] for i in range(len(s))) == (stdout == 'YES')",
      "description": "The output 'YES' indicates that removing one character from s can result in a palindrome."
    },
    {
      "id": "Q3",
      "expression": "all((s[:i] + s[i+1:]) == (s[:i] + s[i+1:])[::-1] for i in range(len(s))) == (stdout == 'NO')",
      "description": "The output 'NO' indicates that removing one character from s cannot result in a palindrome."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "Q >= 1",
      "description": "The number of queries Q must be at least 1."
    },
    {
      "id": "P2",
      "expression": "all(query.startswith('+ ') or query.startswith('? ') for query in queries)",
      "description": "All queries must start with either '+' or '?'."
    },
    {
      "id": "P3",
      "expression": "all(0 <= int(query.split()[1]) <= len(S) if query.startswith('+') else 1 <= int(query.split()[1]) <= len(S) - int(query.split()[2]) + 1 for query in queries)",
      "description": "The indices and lengths in the queries must be within valid bounds."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == 'acb\\nacddb\\n'",
      "description": "The output for the example input must match the expected output."
    },
    {
      "id": "Q2",
      "expression": "all(len(stdout.splitlines()) == sum(1 for query in queries if query.startswith('?')))",
      "description": "The number of output lines must equal the number of '?' queries."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "isinstance(S, str)",
      "description": "The content of the string S must always be a string."
    },
    {
      "id": "I2",
      "expression": "len(S) >= 0",
      "description": "The length of the string S must always be non-negative."
    }
  ]
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 10",
      "description": "The number of test cases T must be between 1 and 10."
    },
    {
      "id": "P2",
      "expression": "1 <= N <= 10**4 and 1 <= Q <= 10**4",
      "description": "The number of houses N and the number of queries Q must be between 1 and 10,000."
    },
    {
      "id": "P3",
      "expression": "1 <= M <= 10**5",
      "description": "The number of bidirectional roads M must be between 1 and 100,000."
    },
    {
      "id": "P4",
      "expression": "1 <= X, Y, A <= N",
      "description": "The house indices X, Y, and A must be valid house numbers between 1 and N."
    },
    {
      "id": "P5",
      "expression": "1 <= K <= 10**4",
      "description": "The time K allowed for each query must be between 1 and 10,000."
    },
    {
      "id": "P6",
      "expression": "1 <= C <= 1000",
      "description": "The cost C of each road must be between 1 and 1,000."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == '0' or all(int(stdout_line) >= 0 for stdout_line in stdout.splitlines())",
      "description": "The output for each query must be non-negative integers, where 0 indicates Mittal cannot visit the friend's house."
    },
    {
      "id": "Q2",
      "expression": "len(stdout.splitlines()) == Q",
      "description": "The number of output lines must match the number of queries Q."
    },
    {
      "id": "Q3",
      "expression": "all(int(stdout_line) <= K - 2 * min_cost for stdout_line in stdout.splitlines())",
      "description": "The maximum playtime for each query must not exceed the allowed time K minus the round trip cost to house A."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 1000",
      "description": "The number of test cases T must be between 1 and 1000."
