  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == str(min_operations)",
      "description": "The output must be the smallest number of operations needed to create a rooted directed tree for each test case."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= a <= 100",
      "description": "The length of the table must be between 1 and 100."
    },
    {
      "id": "P2",
      "expression": "1 <= b <= 100",
      "description": "The width of the table must be between 1 and 100."
