  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 100000",
      "description": "The number of test cases T must be between 1 and 100000."
    },
    {
      "id": "P2",
      "expression": "0 <= k <= 100000",
      "description": "Each test case value k must be between 0 and 100000."
    },
    {
      "id": "P3",
      "expression": "sum(k_values) <= 1000000",
      "description": "The sum of all k values across test cases must not exceed 1000000."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == str(position)",
      "description": "The output must be the final position after k seconds as a string."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= N <= 100",
      "description": "The number of vertices N must be between 1 and 100."
    },
    {
      "id": "P2",
      "expression": "all(1 <= degree <= 1000 for degree in degrees)",
      "description": "Each vertex degree must be between 1 and 1000."
    },
    {
      "id": "P3",
      "expression": "len(degrees) == N",
      "description": "The number of degrees provided must match the number of vertices N."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == 'Yes'",
      "description": "The output is 'Yes' if the graph is a tree."
    },
    {
      "id": "Q2",
      "expression": "stdout == 'No'",
      "description": "The output is 'No' if the graph is not a tree."
    }
  ],
  "invariants": [
    {
      "id": "I1",
      "expression": "sum(degrees) == 2 * (N - 1)",
      "description": "For a graph to be a tree, the sum of the degrees must equal 2 times (N - 1)."
    }
  ]
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 200000",
      "description": "The number of vertices n must be between 1 and 200,000."
    },
    {
      "id": "P2",
      "expression": "0 <= m <= min(n * (n - 1) // 2, 200000)",
      "description": "The number of unordered pairs m must be between 0 and the minimum of n(n-1)/2 and 200,000."
    },
    {
      "id": "P3",
      "expression": "all(1 <= x <= n and 1 <= y <= n and x != y for x, y in pairs)",
      "description": "Each pair (x, y) must consist of distinct integers within the range of 1 to n."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == str(k) + '\\n' + ' '.join(map(str, sizes))",
      "description": "The output must first contain the number of connected components k, followed by the sizes of each component in non-descending order."
    },
    {
      "id": "Q2",
      "expression": "len(sizes) == k",
      "description": "The number of sizes reported must equal the number of connected components k."
    },
    {
      "id": "Q3",
      "expression": "all(size >= 1 for size in sizes)",
      "description": "Each component size must be at least 1, indicating that each component contains at least one vertex."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "2 <= n <= 100000",
      "description": "The number of integers n must be between 2 and 100000 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(1 <= a_i <= 1000000000 for a_i in arr)",
      "description": "Each integer a_i must be between 1 and 10^9 inclusive."
    },
    {
      "id": "P3",
      "expression": "len(arr) == n and len(set(arr)) == n",
      "description": "The input list must contain n distinct integers."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(stdout.split()) == n - 1",
      "description": "The output must contain exactly n - 1 ancestor values."
    },
    {
      "id": "Q2",
      "expression": "all(int(stdout.split()[i]) in {arr[j] for j in range(i + 1)} for i in range(n - 1))",
      "description": "Each output ancestor must be an ancestor of the corresponding input integer in the binary search tree."
    },
    {
      "id": "Q3",
      "expression": "stdout == ' '.join(map(str, expected_output))",
      "description": "The output must match the expected ancestor values for the given input."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= t <= 10000",
      "description": "The number of test cases t is within the range of 1 to 10000."
    },
    {
      "id": "P2",
      "expression": "1 <= n <= 2000 and 1 <= m <= 2000",
      "description": "Each board has dimensions n (rows) and m (columns) within the range of 1 to 2000."
    },
    {
      "id": "P3",
      "expression": "all(len(board[i]) == m for i in range(n))",
      "description": "Each row of the board contains exactly m characters."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "1 <= r <= n and 1 <= c <= m and d >= 0",
      "description": "The output contains valid starting cell coordinates (r, c) and a non-negative integer d representing the maximum number of moves."
    },
    {
      "id": "Q2",
      "expression": "stdout is not None",
      "description": "The output is produced for each test case."
    },
    {
      "id": "Q3",
      "expression": "any((r, c, d) for (r, c, d) in results)",
      "description": "For each test case, there exists at least one valid starting position and move count in the results."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 50000",
      "description": "The number of test cases T must be between 1 and 50000."
    },
    {
      "id": "P2",
      "expression": "all(1 <= len(s) <= 10 for s in test_cases)",
      "description": "Each test case string must have a length between 1 and 10 characters."
    },
    {
      "id": "P3",
      "expression": "all(all(32 <= ord(c) <= 126 for c in s) for s in test_cases)",
      "description": "Each character in the test case strings must have an ASCII code between 32 and 126."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "stdout == 'Error' if not (s[0] in 'abcdefgh' and s[1] in '12345678' and s[2] == '-' and s[3] in 'abcdefgh' and s[4] in '12345678') else stdout",
      "description": "Output 'Error' if the string does not represent a correct pair of cells on the chess board."
    },
    {
      "id": "Q2",
      "expression": "stdout == 'Yes' if (abs(ord(s[0]) - ord(s[3])) == 1 and abs(int(s[1]) - int(s[4])) == 2) or (abs(ord(s[0]) - ord(s[3])) == 2 and abs(int(s[1]) - int(s[4])) == 1) else stdout",
      "description": "Output 'Yes' if the string represents a correct knight move."
    },
    {
      "id": "Q3",
      "expression": "stdout == 'No' if stdout != 'Error' and stdout != 'Yes' else stdout",
      "description": "Output 'No' if the string represents a valid pair of cells but not a knight move."
    }
  ],
  "invariants": []
}

{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= T <= 20000",
      "description": "The number of test cases T must be between 1 and 20000."
    },
    {
      "id": "P2",
      "expression": "2 <= N <= 4",
      "description": "The number of frogs N in each test case must be between 2 and 4."
    },
    {
      "id": "P3",
      "expression": "all(1 <= W[i] <= N for i in range(N))",
      "description": "The weights of the frogs must be distinct integers between 1 and N."
    },
    {
      "id": "P4",
      "expression": "all(1 <= L[i] <= 5 for i in range(N))",
      "description": "The jump distances L of the frogs must be integers between 1 and 5."
