  public double Y;

  public Point(double x, double y)
  {
    this.X = x;
    this.Y = y;
  }

  public override string ToString()
  {
    return $"({this.X}, {this.Y})";
  }

  public override bool Equals(object point)
  {
    // Typechecking
    if (point == null || point.GetType() != this.GetType())
    {
      return false;
    }

    return this.ToString() == point.ToString();
  }
}
